// src/App.tsx — social batch review calendar (template).
// Static app: all content lives in POSTS. No backend calls, nothing to seed.
// Image constants come from src/visuals.ts, generated by scripts/encode_visuals.py.
// Replace ACCOUNTS, WEEKS, POSTS, TITLE and BOUNDARY; leave the components alone.

import { useMemo, useState } from "react";
import * as VIS from "./visuals";

const V = VIS as unknown as Record<string, { src: string; file: string; w: number; h: number }>;

// ---- Batch content (edit this block) ---------------------------------------

const TITLE = "Example Co · LinkedIn and X · November batch";
const BOUNDARY =
  "Every caption below is the current text and can be copied as written. Nothing here is approved for publishing until its card says Approved. Approvers are named on each card.";

const ACCOUNTS = ["Company LinkedIn", "Founder LinkedIn", "Company X"] as const;
type Account = (typeof ACCOUNTS)[number];

// Chip colour per account: one of "info" | "success" | "warning" | "neutral".
const ACCOUNT_TONE: Record<Account, string> = {
  "Company LinkedIn": "info",
  "Founder LinkedIn": "success",
  "Company X": "warning",
};

const WEEKS = ["Week 1 · Nov 3", "Week 2 · Nov 10"];
const DAYS = ["Mon", "Tue", "Wed", "Thu", "Fri"] as const;
type Day = (typeof DAYS)[number];

type Visual = { key: string; label: string };

type Post = {
  n: number;
  week: string; // must match an entry in WEEKS
  day: Day;
  time?: string; // leave empty if posting times aren't agreed
  account: Account;
  handle: string;
  story: string;
  approver: string;
  state: "Draft" | "In review" | "Approved" | "Scheduled" | "Posted";
  caption: string; // paragraphs separated by a blank line
  visuals: Visual[]; // first one is the primary; the rest are labelled alternatives
  notes: string; // open decisions and day-of checks
};

const POSTS: Post[] = [
  {
    n: 1,
    week: "Week 1 · Nov 3",
    day: "Tue",
    account: "Company LinkedIn",
    handle: "Example Co page",
    story: "Launch: shared review calendar",
    approver: "Dana (founder)",
    state: "In review",
    caption:
      "Example Co customers can now review a whole month of posts on one calendar.\n\nEach card shows the full caption as text you can copy, the image under it, and who approves it.\n\n> How it works: [link]",
    visuals: [{ key: "sample1", label: "Primary · 1200×1200" }],
    notes: "Day-of check: confirm the link resolves before posting. Link goes in the first comment.",
  },
  {
    n: 2,
    week: "Week 1 · Nov 3",
    day: "Thu",
    account: "Founder LinkedIn",
    handle: "Dana Lee",
    story: "Why we stopped sending PDFs",
    approver: "Dana",
    state: "Draft",
    caption:
      "We used to send clients a PDF of next month's posts, and every month someone retyped a caption by hand.\n\nNow they get a calendar with the caption as real text and the image right under it. Review time on our side went from a week of back-and-forth to one call.",
    visuals: [],
    notes: "Text-only on purpose.",
  },
];

// ---- Components (no edits needed) ------------------------------------------

function paragraphsOf(caption: string) {
  return caption.split(/\n\s*\n/);
}

function stateTone(state: Post["state"]) {
  if (state === "Approved" || state === "Scheduled" || state === "Posted") return "badge badge-success";
  if (state === "In review") return "badge badge-warning";
  return "badge";
}

function CopyButton({ text }: { text: string }) {
  const [copied, setCopied] = useState(false);
  async function copy() {
    try {
      await navigator.clipboard.writeText(text);
      setCopied(true);
      window.setTimeout(() => setCopied(false), 1800);
    } catch {
      setCopied(false);
    }
  }
  return (
    <button type="button" className="button button-primary" onClick={copy}>
      {copied ? "Copied" : "Copy caption"}
    </button>
  );
}

function VisualFigure({ visual }: { visual: Visual }) {
  const img = V[visual.key];
  if (!img) return <p className="text-secondary">Missing visual: {visual.key}</p>;
  return (
    <figure className="post-visual">
      <img src={img.src} alt={visual.label} loading="lazy" />
      <figcaption className="row">
        <span className="text-secondary">
          {visual.label} · {img.w}×{img.h}
        </span>
        <a className="button" href={img.src} download={img.file}>
          Download {img.file}
        </a>
      </figcaption>
    </figure>
  );
}

function AccountChip({ account }: { account: Account }) {
  return <span className={`badge badge-${ACCOUNT_TONE[account]}`}>{account}</span>;
}

function PostDetail({ post }: { post: Post }) {
  return (
    <article className="card post-card" id={`post-${post.n}`}>
      <div className="post-head">
        <div>
          <span className="text-label">
            Post {post.n} · {post.week} · {post.day}
            {post.time ? ` · ${post.time}` : ""}
          </span>
          <h2 className="post-title">
            {post.account} <span className="text-secondary">· {post.handle}</span>
          </h2>
          <p className="text-secondary">
            {post.story} · {post.approver} approves
          </p>
        </div>
        <span className={stateTone(post.state)}>{post.state}</span>
      </div>
      <div className="post-caption">
        {paragraphsOf(post.caption).map((p, i) => (
          <p key={i}>{p}</p>
        ))}
      </div>
      <div className="row post-actions">
        <CopyButton text={post.caption} />
        <span className="text-secondary">{post.caption.length} characters</span>
      </div>
      {post.visuals.length > 0 ? (
        <div className="post-visuals">
          {post.visuals.map((v) => (
            <VisualFigure key={v.key} visual={v} />
          ))}
        </div>
      ) : (
        <p className="text-secondary">No visual: text-only post.</p>
      )}
      {post.notes ? <p className="text-secondary post-notes">Notes: {post.notes}</p> : null}
    </article>
  );
}

function CalendarTile({ post, onOpen }: { post: Post; onOpen: () => void }) {
  const paras = paragraphsOf(post.caption);
  const first = post.visuals[0] ? V[post.visuals[0].key] : undefined;
  return (
    <button type="button" className="tile" onClick={onOpen}>
      <span className="row tile-head">
        <AccountChip account={post.account} />
        <span className={stateTone(post.state)}>{post.state}</span>
      </span>
      {first ? <img className="tile-img" src={first.src} alt={post.visuals[0].label} loading="lazy" /> : null}
      <span className="tile-text">{paras[0]}</span>
      {paras.length > 1 ? (
        <span className="text-secondary text-small">
          + {paras.length - 1} more paragraph{paras.length > 2 ? "s" : ""} · open
        </span>
      ) : (
        <span className="text-secondary text-small">open</span>
      )}
    </button>
  );
}

export function App() {
  const [filter, setFilter] = useState<"All" | Account>("All");
  const [view, setView] = useState<"Calendar" | "List">("Calendar");
  const [open, setOpen] = useState<number | null>(null);

  const visible = useMemo(
    () => (filter === "All" ? POSTS : POSTS.filter((p) => p.account === filter)),
    [filter],
  );
  const opened = POSTS.find((p) => p.n === open) ?? null;

  return (
    <main className="app-shell wide">
      <header className="calendar-header">
        <h1>{TITLE}</h1>
        <p className="text-secondary">{BOUNDARY}</p>
      </header>

      <section className="card schedule">
        <h2 className="text-label">Schedule</h2>
        <ul className="schedule-list">
          {POSTS.map((p) => (
            <li key={p.n}>
              <span className="schedule-when">
                {p.week} · {p.day}
                {p.time ? ` · ${p.time}` : ""}
              </span>
              <span className="schedule-account">{p.account}</span>
              <span className="text-secondary">{p.story}</span>
            </li>
          ))}
        </ul>
      </section>

      <div className="row toolbar">
        <div className="row filters">
          {(["All", ...ACCOUNTS] as Array<"All" | Account>).map((opt) => (
            <button
              key={opt}
              type="button"
              className={opt === filter ? "button button-primary" : "button"}
              onClick={() => setFilter(opt)}
            >
              {opt}
            </button>
          ))}
        </div>
        <div className="row">
          {(["Calendar", "List"] as const).map((v) => (
            <button
              key={v}
              type="button"
              className={v === view ? "button button-primary" : "button"}
              onClick={() => {
                setView(v);
                setOpen(null);
              }}
            >
              {v}
            </button>
          ))}
        </div>
      </div>

      {opened ? (
        <div className="detail">
          <button type="button" className="button" onClick={() => setOpen(null)}>
            ← Back to {view.toLowerCase()}
          </button>
          <PostDetail post={opened} />
        </div>
      ) : view === "Calendar" ? (
        WEEKS.map((week) => (
          <section key={week} className="week">
            <h2 className="text-label">{week}</h2>
            <div className="week-scroll">
              <div className="week-grid">
                {DAYS.map((day) => (
                  <div key={day} className="day-col">
                    <span className="text-secondary text-small day-name">{day}</span>
                    {visible
                      .filter((p) => p.week === week && p.day === day)
                      .map((p) => (
                        <CalendarTile key={p.n} post={p} onOpen={() => setOpen(p.n)} />
                      ))}
                  </div>
                ))}
              </div>
            </div>
          </section>
        ))
      ) : (
        visible.map((p) => <PostDetail key={p.n} post={p} />)
      )}
    </main>
  );
}
